---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Command palette: Jump anywhere or hand a task to the agent from one box.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change command-palette.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './command-palette.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="command-palette" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="cpl panel">
  <div class="cpl-in"><svg class="i s"><use href="#i-search"/></svg><input class="cpl-q" placeholder="Search or ask the agent" aria-label="Command" spellcheck="false"><span class="kbd">esc</span></div>
  <div class="cpl-list" role="listbox"></div>
  <div class="cpl-f muted"><span class="cpl-st"></span><span><span class="kbd">↑</span><span class="kbd">↓</span> move</span><span><span class="kbd">↵</span> run</span></div>
</div>
  </Fragment></div>
</div>
<script>
  import './command-palette.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Command palette ---------- */
/* one quiet box: each command has a tile in its group's hue and a muted hint after its name; a grey highlight glides to the
   row the arrows are on, and a command that runs turns its tile into a spinner for a beat. Its content sits 16px in from every
   edge (owner, 18 Nov): the glass, the group names, the tiles and the footer's words on the left, esc, the shortcuts and the
   footer's keys on the right; the rows' highlight reaches 8px out round them. The list is as tall as what it shows, up to six
   rows or so, and the box eases to its new height as a search narrows it (grow(), centred in its stage): no room is kept */
.cpl{display:flex;flex-direction:column;box-shadow:var(--dm-shadow-pop)}
.cpl-in{display:flex;align-items:center;gap:10px;padding:var(--dm-s-3) var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-muted)}
.cpl-q{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:14px;color:var(--dm-fg);caret-color:var(--dm-accent-fg,var(--dm-fg))}
.cpl-q::placeholder{color:var(--dm-muted)}
/* the line under the search box steps up while it has the focus; a row that takes the focus rings on its own */
.cpl-list{padding:var(--dm-s-2);max-height:236px;overflow-y:auto;position:relative}
/* while there is more list below, its last row fades out at the edge instead of being cut off by the footer */
.cpl-list.more{-webkit-mask-image:linear-gradient(to bottom,#000 calc(100% - 32px),transparent);mask-image:linear-gradient(to bottom,#000 calc(100% - 32px),transparent)}
.cpl-g{font-size:11.5px;color:var(--dm-muted);padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-1)}
.cpl-i{display:flex;align-items:center;gap:10px;width:100%;height:36px;padding:0 var(--dm-s-2);border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13.5px;text-align:left;color:var(--dm-fg);position:relative;z-index:1}
/* rows arrive in a short cascade when the list narrows */
.cpl-i.in{animation:cplin .32s var(--dm-ease) backwards}
@keyframes cplin{from{opacity:0;transform:translateY(4px)}}
.cpl-i .ic{width:24px;height:24px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;color:var(--dm-tc,var(--dm-fg2));background:var(--dm-tb,var(--dm-chip));transition:background .2s,color .2s,transform .2s var(--dm-ease)}
.cpl-i.hl .ic{transform:scale(1.06)}
.cpl-i .ic .spin{width:11px;height:11px}
/* a label too long for a narrow palette ends in an ellipsis on its one line, so it never spills out of its row; the hint
   gives way first */
.cpl-i .t{flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cpl-i .h{flex:1 1 0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12.5px;color:var(--dm-muted)}
.cpl-i.hl .h{color:var(--dm-fg2)}
.cpl-i .k{margin-left:auto;display:flex;gap:var(--dm-s-1);flex:none}
.cpl-i mark{background:transparent;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500}
/* the row that hands the text to the agent: an accent tile, the words in quotes, and Enter shown while it is highlighted */
.cpl-i.ask .ic{background:var(--dm-accent);color:var(--dm-on-accent)}
.cpl-i.ask .q{color:var(--dm-fg2)}
.cpl-i .ent{margin-left:auto;opacity:0;transition:opacity .2s}
.cpl-i.hl .ent{opacity:1}
.cpl-hl{position:absolute;left:var(--dm-s-2);right:var(--dm-s-2);height:36px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-row);transition:top .25s var(--dm-ease);z-index:0}
/* the footer: what ran last on the left, the keys on the right (they keep their room; the words give way first) */
.cpl-f{display:flex;gap:14px;align-items:center;padding:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:11.5px}
.cpl-f>span{flex:none;white-space:nowrap}
/* (the foot's key chips are blocks of their own, as tall as every other key chip) */
.cpl-f .kbd{display:inline-block;margin-right:var(--dm-s-1)}
.cpl-f>.cpl-st{flex:1 1 auto;min-width:0;color:var(--dm-fg2);overflow:hidden;text-overflow:ellipsis}
/* (a footer that lists the keys first keeps what ran at its right end) */
.cpl-f>.cpl-st:last-child{flex:0 1 auto;margin-left:auto}
.cpl-st .dot{color:var(--dm-ok-mark);margin-right:6px;vertical-align:1px}
.cpl-empty{padding:30px 10px;text-align:center;font-size:13px;color:var(--dm-muted)}
:root:not([data-style="soft"],[data-style="clean"]) .cpl-i.hl .ic:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){transform:none}
:root:not([data-style="soft"],[data-style="clean"]) .cpl-i.in:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){animation:bpin .3s var(--dm-ease) backwards}
/* Clean (owner, 18 Nov): the tiles are one neutral grey with a hairline (the groups' hues carry no meaning here), and the row that
   hands the text to the agent has the ink tile of Clean's primary; the letters a search matches read in the text colour, a step
   heavier. The rows' highlight is concentric with the card (14px, 8px in), nothing grows under the pointer, and the footer is an
   off-white foot strip, edge to edge, its words and keys 16px in */
:root[data-style="clean"] .cpl-i .ic,:root [data-style="clean"] .cpl-i .ic,:root [data-style="clean"].cpl-i .ic{color:var(--dm-fg2);background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .cpl-i.ask .ic,:root [data-style="clean"] .cpl-i.ask .ic,:root [data-style="clean"].cpl-i.ask .ic{color:var(--dm-on-btn);background:linear-gradient(180deg,var(--dm-btn-1),var(--dm-btn-2));box-shadow:none}
:root[data-style="clean"] .cpl-i.hl .ic,:root [data-style="clean"] .cpl-i.hl .ic,:root [data-style="clean"].cpl-i.hl .ic{transform:none}
:root[data-style="clean"] .cpl-i.hl:not(.ask) .ic,:root [data-style="clean"] .cpl-i.hl:not(.ask) .ic,:root [data-style="clean"].cpl-i.hl:not(.ask) .ic{background:var(--dm-surface)}
:root[data-style="clean"] .cpl-i mark,:root [data-style="clean"] .cpl-i mark,:root [data-style="clean"].cpl-i mark{color:var(--dm-fg)}
:root[data-style="clean"] :is(.cpl-i,.cpl-hl),:root [data-style="clean"] :is(.cpl-i,.cpl-hl),:root [data-style="clean"]:is(.cpl-i,.cpl-hl){border-radius:calc(var(--dm-r-card) - 8px)}
:root[data-style="clean"] .cpl-hl,:root [data-style="clean"] .cpl-hl,:root [data-style="clean"].cpl-hl{transition:top var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .cpl-list.hg .cpl-hl,:root [data-style="clean"] .cpl-list.hg .cpl-hl,:root [data-style="clean"].cpl-list.hg .cpl-hl{display:none}
:root[data-style="clean"] .cpl-i.in,:root [data-style="clean"] .cpl-i.in,:root [data-style="clean"].cpl-i.in{animation:clpiece var(--dm-t) var(--dm-ease) backwards}
/* the foot strip is as tall as a strip with a control (44px), so its words sit as far from the card's foot as its sides (16px);
   the list gives up those 10px, so Clean's palette is no taller than Soft's */
:root[data-style="clean"] .cpl-f,:root [data-style="clean"] .cpl-f,:root [data-style="clean"].cpl-f{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);padding:var(--dm-s-2) var(--dm-s-4);background:var(--dm-strip);border-top-color:var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .cpl-list,:root [data-style="clean"] .cpl-list,:root [data-style="clean"].cpl-list{max-height:226px}
:root[data-style="clean"] .cpl-f .kbd,:root [data-style="clean"] .cpl-f .kbd,:root [data-style="clean"].cpl-f .kbd{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-hair)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, enter, grow, hoverGlide, swap } from '../core/core.js';
DM.def('command-palette', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{search}', I('search'));
  // Clean's one hover: a highlight that glides from row to row (hoverGlide)
  c.offs.push(hoverGlide($('.cpl-list', r), '.cpl-i'));
  // [group, icon, label, keys, hint]; each group's tiles take its hue
  const C = [
    ['Agent','spark','Audit this page for contrast',['⌘','J'],'WCAG AA'],
    ['Agent','wand','Tidy layer names in the selection',null,'12 layers'],
    ['Agent','code','Export tokens as CSS variables',null,'tokens.css'],
    ['Go to','layers','Pricing v4',['G','P'],'Page'],
    ['Go to','figma','Checkout flow',null,'Figma file'],
    ['Go to','book','Memory',null,'Team notes'],
    ['Actions','users','Invite a teammate',null,'Acme Labs'],
    ['Actions','gear','Agent settings',['⌘',',']],
    ['Actions','palette','Switch theme',null,'Light']
  ];
  const TONE = { Agent:'pl', 'Go to':'pb', Actions:'pt' };
  const q = $('.cpl-q', r), list = $('.cpl-list', r), st = $('.cpl-st', r);
  list.id = 'cpl-l-' + Math.random().toString(36).slice(2, 7); list.setAttribute('aria-label', 'Commands'); list.tabIndex = -1;
  q.setAttribute('role', 'combobox'); q.setAttribute('aria-expanded', 'true'); q.setAttribute('aria-controls', list.id); q.setAttribute('aria-autocomplete', 'list');
  let items = [], hi = 0, last = C.map(x => x[2]).join('|');
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  function paint(){
    const v = q.value.trim(), re = v ? new RegExp('(' + v.split('').map(esc).join(').*?(') + ')', 'i') : null;
    const m = C.filter(x => !re || re.test(x[2]));
    // the rows play a short cascade only when the list changes, not on every letter that keeps it as it is
    const key = m.map(x => x[2]).join('|') + (v ? '|ask' : ''), fresh = key !== last; last = key;
    let h = '<span class="cpl-hl"></span>', g = '', n = 0;
    const cls = () => fresh ? ` in" style="animation-delay:${Math.min(n++, 6) * 28}ms` : '';
    m.forEach(x => { if (x[0] !== g){ g = x[0]; h += `<div class="cpl-g">${g}</div>`; } const label = v ? x[2].replace(new RegExp(v.split('').map(esc).join('|'), 'gi'), s => `<mark>${s}</mark>`) : x[2], t = TONE[x[0]];
      h += `<button class="cpl-i${cls()}" role="option" data-t="${x[2]}"><span class="ic" style="--dm-tc:var(--dm-${t});--dm-tb:var(--dm-${t}-bg)">${I(x[1],'xs')}</span><span class="t">${label}</span>${x[4] ? `<span class="h">${x[4]}</span>` : ''}${x[3] ? `<span class="k">${x[3].map(k => `<span class="kbd">${k}</span>`).join('')}</span>` : ''}</button>`; });
    if (v) h += `<div class="cpl-g">Ask</div><button class="cpl-i ask${cls()}" data-t="${v.replace(/"/g,'&quot;')}" data-ask="1"><span class="ic">${I('spark','xs')}</span><span class="t">Ask the agent <span class="q">“${v.replace(/</g,'&lt;')}”</span></span><span class="kbd ent">↵</span></button>`;
    list.innerHTML = h; items = $$('.cpl-i', list); hi = 0;
    // the search box keeps the focus and points at the highlighted row (aria-activedescendant), so the rows are not tab stops
    items.forEach((b, i) => { b.id = list.id + '-' + i; b.tabIndex = -1; b.setAttribute('role', 'option'); b.onmouseenter = () => move(i - hi); b.onclick = () => run(b); });
    if (!items.length) q.removeAttribute('aria-activedescendant'); move(0); edge();
  }
  function move(d){ if (!items.length) return; hi = (hi + d + items.length) % items.length; items.forEach((b, i) => { b.classList.toggle('hl', i === hi); b.setAttribute('aria-selected', i === hi); }); const b = items[hi], hl = $('.cpl-hl', list); q.setAttribute('aria-activedescendant', b.id); hl.style.top = b.offsetTop + 'px'; if (b.offsetTop < list.scrollTop || b.offsetTop + 36 > list.scrollTop + list.clientHeight) list.scrollTo({ top:b.offsetTop - 40, behavior:REDUCE ? 'auto' : 'smooth' }); }
  const edge = () => list.classList.toggle('more', list.scrollTop + list.clientHeight < list.scrollHeight - 2);
  c.on(list, 'scroll', edge, { passive:true });
  // a command that runs turns its tile into a spinner for a beat, then the footer says what ran
  // (nothing in it scales when pressed, owner 18 Nov)
  function run(b){
    const ic = $('.ic', b), was = ic.innerHTML; ic.innerHTML = '<span class="spin"></span>';
    setTimeout(() => { if (ic.isConnected){ ic.innerHTML = was; enter(ic.firstElementChild); } swap(st, `<span class="dot"></span>${b.dataset.ask ? 'Sent to the agent' : 'Ran: ' + b.dataset.t}`, true); }, REDUCE ? 0 : 650);
  }
  q.oninput = paint;
  q.onkeydown = e => { if (e.key === 'ArrowDown'){ move(1); e.preventDefault(); } else if (e.key === 'ArrowUp'){ move(-1); e.preventDefault(); } else if (e.key === 'Enter' && items[hi]) run(items[hi]); else if (e.key === 'Escape'){ q.value = ''; paint(); } };
  paint();
  // no room is kept for a longer list (owner, 18 Nov): the box is as tall as what it shows and eases to its new height as a
  // search narrows or widens it (grow(), centred in its stage), once its entrance (which scales it) has ended
  const pal = r.classList.contains('cpl') ? r : $('.cpl', r);
  if (pal && r === c.st) Promise.resolve().then(() => Promise.all(pal.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && pal.isConnected) c.offs.push(grow(pal)); });
  // the preview's story: someone types "tok" and runs the token export, then looks for "invi" and runs the invite; clicking,
  // focusing or typing in it takes over, and what it had typed goes
  c.story(async s => {
    await s.beat(3);
    await s.type(q, 'tok', { n:.36, each:paint });
    await s.beat(2); run(items[hi]); await s.beat(4);
    await s.type(q, '', { n:.36, each:paint, clear:true }); await s.beat(1);
    await s.type(q, 'invi', { n:.36, each:paint });
    await s.beat(2); run(items[hi]); await s.beat(4);
  });
});
